const j = $json || {};
const jobId = (j.jobId || "").trim();
const title = (j.title || "").trim();
const template = (j.template || "").trim();
const data = j.data || {};

const validTemplates = [
  "stats-grid", "process-steps", "comparison", "timeline",
  "checklist", "cost-breakdown", "before-after-explanation", "faq-summary"
];

if (!jobId) {
  return { ok: false, errorCode: "INVALID_INPUT", errorMessage: "jobId is required for infographic renderer." };
}
if (!title) {
  return { ok: false, errorCode: "INVALID_INPUT", errorMessage: "title is required for infographic renderer." };
}
if (!template || !validTemplates.includes(template)) {
  return { ok: false, errorCode: "INVALID_TEMPLATE", errorMessage: "template must be one of: " + validTemplates.join(", ") };
}
if (!data || typeof data !== "object") {
  return { ok: false, errorCode: "INVALID_DATA", errorMessage: "data object is required to populate infographic template: " + template };
}

return {
  jobId,
  template,
  title,
  data,
  ok: true
};

const p = $("02 Validate Infographic Input").item.json;

function escapeXml(str) {
  if (!str) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

const title = escapeXml(p.title);
const template = p.template;
const data = p.data || {};
const width = 1080;
const height = 1080;
let innerSvg = "";

if (template === "stats-grid") {
  const stats = Array.isArray(data.stats) ? data.stats : [{ label: "النتيجة", value: "98%" }, { label: "العملاء", value: "+5000" }, { label: "الخبرة", value: "15 عاماً" }, { label: "التقييم", value: "4.9/5" }];
  innerSvg = stats.slice(0, 4).map((s, idx) => {
    const col = idx % 2;
    const row = Math.floor(idx / 2);
    const x = 80 + col * 470;
    const y = 240 + row * 360;
    return `<g transform="translate(${x}, ${y})">
      <rect width="430" height="320" fill="#1e293b" rx="16" stroke="#38bdf8" stroke-width="2"/>
      <text x="215" y="140" fill="#38bdf8" font-family="sans-serif" font-size="64" font-weight="bold" text-anchor="middle">${escapeXml(s.value)}</text>
      <text x="215" y="220" fill="#cbd5e1" font-family="sans-serif" font-size="28" text-anchor="middle">${escapeXml(s.label)}</text>
    </g>`;
  }).join("");
} else if (template === "process-steps") {
  const steps = Array.isArray(data.steps) ? data.steps : ["الاستشارة والتقييم", "التخطيط الطبي", "الربط والتنفيذ", "المتابعة والتعافي"];
  innerSvg = steps.slice(0, 4).map((step, idx) => {
    const y = 240 + idx * 180;
    return `<g transform="translate(80, ${y})">
      <rect width="920" height="140" fill="#1e293b" rx="12" stroke="#6366f1" stroke-width="2"/>
      <circle cx="80" cy="70" r="40" fill="#6366f1"/>
      <text x="80" y="80" fill="#ffffff" font-family="sans-serif" font-size="32" font-weight="bold" text-anchor="middle">${idx + 1}</text>
      <text x="160" y="82" fill="#f8fafc" font-family="sans-serif" font-size="30">${escapeXml(step)}</text>
    </g>`;
  }).join("");
} else if (template === "comparison") {
  const items = Array.isArray(data.items) ? data.items : [{ feature: "الضمان", optionA: "شامل", optionB: "محدود" }, { feature: "التقنية", optionA: "حديثة DHI", optionB: "تقليدية" }];
  innerSvg = `<rect x="80" y="240" width="920" height="720" fill="#1e293b" rx="16" stroke="#334155" stroke-width="2"/>
  <line x1="540" y1="240" x2="540" y2="960" stroke="#334155" stroke-width="2"/>
  <text x="310" y="290" fill="#38bdf8" font-family="sans-serif" font-size="32" font-weight="bold" text-anchor="middle">الخيار الأول</text>
  <text x="770" y="290" fill="#94a3b8" font-family="sans-serif" font-size="32" font-weight="bold" text-anchor="middle">الخيار الثاني</text>
  ` + items.slice(0, 4).map((it, idx) => {
    const y = 380 + idx * 130;
    return `<text x="310" y="${y}" fill="#ffffff" font-family="sans-serif" font-size="26" text-anchor="middle">${escapeXml(it.optionA || it.feature)}</text>
    <text x="770" y="${y}" fill="#cbd5e1" font-family="sans-serif" font-size="26" text-anchor="middle">${escapeXml(it.optionB || "-")}</text>`;
  }).join("");
} else if (template === "timeline") {
  const events = Array.isArray(data.events) ? data.events : [{ time: "اليوم 1", title: "العملية" }, { time: "الأسبوع 2", title: "التعافي الأول" }, { time: "الشهر 6", title: "نمو الشعر" }, { time: "الشهر 12", title: "النتيجة النهائية" }];
  innerSvg = events.slice(0, 4).map((ev, idx) => {
    const y = 240 + idx * 180;
    return `<g transform="translate(80, ${y})">
      <rect width="920" height="140" fill="#0f172a" rx="12" stroke="#0284c7" stroke-width="2"/>
      <text x="40" y="80" fill="#38bdf8" font-family="sans-serif" font-size="28" font-weight="bold">${escapeXml(ev.time)}</text>
      <text x="280" y="80" fill="#ffffff" font-family="sans-serif" font-size="28">${escapeXml(ev.title)}</text>
    </g>`;
  }).join("");
} else if (template === "checklist") {
  const list = Array.isArray(data.list) ? data.list : ["الفحوصات الطبية اللازمة", "التوقف عن التدخين قبل العملية", "الالتزام بتعليمات الطبيب", "تناول الفيتامينات الموصى بها"];
  innerSvg = list.slice(0, 5).map((item, idx) => {
    const y = 240 + idx * 140;
    return `<g transform="translate(80, ${y})">
      <rect width="920" height="110" fill="#1e293b" rx="10" stroke="#10b981" stroke-width="2"/>
      <text x="40" y="68" fill="#10b981" font-family="sans-serif" font-size="36" font-weight="bold">✓</text>
      <text x="110" y="66" fill="#f8fafc" font-family="sans-serif" font-size="26">${escapeXml(item)}</text>
    </g>`;
  }).join("");
} else if (template === "cost-breakdown") {
  const costs = Array.isArray(data.costs) ? data.costs : [{ item: "العملية الأساسية", cost: "$1500" }, { label: "العملية الأساسية", cost: "$1500" }, { item: "الإقامة والفيلا", cost: "$400" }, { item: "المواصلات", cost: "$200" }];
  innerSvg = costs.slice(0, 4).map((c, idx) => {
    const y = 240 + idx * 170;
    const name = escapeXml(c.item || c.label || "بند التكلفة");
    const price = escapeXml(c.cost || c.price || "$0");
    return `<g transform="translate(80, ${y})">
      <rect width="920" height="130" fill="#1e293b" rx="12" stroke="#f59e0b" stroke-width="2"/>
      <text x="50" y="75" fill="#ffffff" font-family="sans-serif" font-size="28">${name}</text>
      <text x="870" y="75" fill="#f59e0b" font-family="sans-serif" font-size="32" font-weight="bold" text-anchor="end">${price}</text>
    </g>`;
  }).join("");
} else if (template === "before-after-explanation") {
  const points = Array.isArray(data.points) ? data.points : ["تغطية كاملة للمناطق المصابة", "كثافة عالية وطبيعية", "بدون آثار جراحية ظاهرية"];
  innerSvg = `<rect x="80" y="240" width="920" height="360" fill="#1e293b" rx="16" stroke="#ec4899" stroke-width="2"/>
  <text x="540" y="430" fill="#ec4899" font-family="sans-serif" font-size="36" font-weight="bold" text-anchor="middle">توضيح النتائج قبل وبعد</text>
  ` + points.slice(0, 3).map((pt, idx) => {
    const y = 650 + idx * 110;
    return `<g transform="translate(80, ${y})">
      <rect width="920" height="90" fill="#0f172a" rx="8" stroke="#334155" stroke-width="1"/>
      <text x="40" y="55" fill="#cbd5e1" font-family="sans-serif" font-size="24">• ${escapeXml(pt)}</text>
    </g>`;
  }).join("");
} else {
  // faq-summary
  const faqs = Array.isArray(data.faqs) ? data.faqs : [{ question: "كم تستغرق العملية؟", answer: "من 6 إلى 8 ساعات" }, { question: "متى تظهر النتائج؟", answer: "خلال 6 إلى 12 شهراً" }];
  innerSvg = faqs.slice(0, 3).map((faq, idx) => {
    const y = 240 + idx * 240;
    return `<g transform="translate(80, ${y})">
      <rect width="920" height="200" fill="#1e293b" rx="14" stroke="#8b5cf6" stroke-width="2"/>
      <text x="40" y="70" fill="#c084fc" font-family="sans-serif" font-size="28" font-weight="bold">س: ${escapeXml(faq.question)}</text>
      <text x="40" y="140" fill="#ffffff" font-family="sans-serif" font-size="24">ج: ${escapeXml(faq.answer)}</text>
    </g>`;
  }).join("");
}

const svgContent = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <rect width="100%" height="100%" fill="#0f172a"/>
  <rect x="30" y="30" width="1020" height="1020" fill="none" stroke="#38bdf8" stroke-width="4" rx="24"/>
  <text x="60" y="120" fill="#38bdf8" font-family="sans-serif" font-size="40" font-weight="bold">${title}</text>
  <text x="60" y="175" fill="#94a3b8" font-family="sans-serif" font-size="22">Template: ${template}</text>
  ${innerSvg}
</svg>`;

const binaryBuffer = Buffer.from(svgContent, "utf-8");
const base64Data = binaryBuffer.toString("base64");

return {
  json: {
    jobId: p.jobId,
    assetKey: `infographic-${p.template}-1`,
    assetType: "infographic",
    template: p.template,
    width,
    height,
    fileSizeBytes: binaryBuffer.length,
    mimeType: "image/svg+xml",
    ok: true
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: "image/svg+xml",
      fileName: `infographic-${p.template}.svg`,
      fileExtension: "svg",
      fileSize: `${binaryBuffer.length} B`
    }
  }
};

const item = $input.item;
const meta = item.json || {};
const hasBinary = item.binary && item.binary.data && item.binary.data.data;

if (!hasBinary) {
  return {
    json: {
      success: false,
      jobId: meta.jobId || null,
      status: "FAILED",
      message: "Infographic rendering failed — no binary image output produced.",
      data: null,
      warnings: [],
      errors: [{ code: "RENDER_FAILED", language: null, path: null, message: "Infographic renderer did not produce binary output data." }],
      nextAllowedActions: ["retry", "cancel"]
    },
    binary: item.binary
  };
}

const norm = {
  success: true,
  jobId: meta.jobId,
  status: "ASSET_GENERATED",
  message: "Infographic rendered successfully using template: " + meta.template,
  data: {
    assetKey: meta.assetKey,
    assetType: meta.assetType,
    template: meta.template,
    width: meta.width,
    height: meta.height,
    fileSizeBytes: meta.fileSizeBytes,
    mimeType: meta.mimeType
  },
  warnings: [],
  errors: [],
  nextAllowedActions: ["optimize_images"]
};

return {
  json: norm,
  binary: item.binary
};

const j = $json || {};
const code = j.errorCode || "INVALID_TEMPLATE";
const message = j.errorMessage || "Invalid infographic template selection or input data.";
return {
  json: {
    success: false,
    jobId: j.jobId || null,
    status: "FAILED",
    message,
    data: null,
    warnings: [],
    errors: [{ code, language: null, path: null, message }],
    nextAllowedActions: ["cancel"]
  },
  binary: $input.item ? $input.item.binary : undefined
};
